import { GUARDAREMPRESA } from "../Action-Tipes.js/actions-type-empresa"
import axios from "axios"


export const Registrar_Empresa = (userData) =>{
    return async (dispatch) =>{
        try {
         //   const endpoint = `http://localhost:3001/user/${correo}/${pass}`; // Usamos los datos en la URL como parámetros de ruta
         const datos = {
            name:userData.name,
            Descripcion:"",
            celular:"",
            correo:userData.mail,
            password:userData.clave,
            url:""
         }
         const endpoint = `http://localhost:3001/crear/empresa`;
         const response = await axios.post(endpoint);
            const userData = response.data; 
            const  user = userData.data


       
        dispatch({
            type: GUARDAREMPRESA,
            payload: user,
        })
        return userData;
    } catch (error) {
        console.log("Error al enviar la información", error.message);
    }
    }


}
